using System;using System.IO;using System.Xml;using System.Text;using System.Reflection;using System.Collections.Generic;
public static class BatchTwoSaveWorker {
 static string Inventory(Chunk c){var s=new StringBuilder();foreach(var te in c.GetTileEntities().list){var t=te as TileEntityComposite;var st=t==null?null:t.GetFeature<TEFeatureStorage>();if(st==null)continue;s.Append(te.localChunkPos+":");foreach(var i in st.ItemGrid.CloneItems())s.Append(i.itemValue.type+"/"+i.count+"/"+i.itemValue.Quality+",");s.AppendLine();}return s.ToString();}
 public static string Run(string mode){if(!GameIO.GetUserGameDataDir().Replace('\\','/').EndsWith("/BatchThreeSave"))throw new Exception("Disposable BatchThreeSave required");bool apply=mode=="apply";var world=GameManager.Instance.World;if(world.GetPlayers().Count!=0)throw new Exception("Players connected");string folder=ModManager.GetMod("BatchTwoSaveTools",true).Path;var manager=(RegionFileManager)typeof(ChunkProviderGenerateWorld).GetField("m_RegionFileManager",BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance).GetValue(world.ChunkCache.ChunkProvider);var chunks=new Dictionary<string,Chunk>();var dirty=new HashSet<Chunk>();var report=new StringBuilder();foreach(long key in manager.GetAllChunkKeys()){var c=manager.GetChunkSync(key);if(c==null)throw new Exception("Unreadable chunk");chunks[c.X+","+c.Z]=c;}
 var prefab=new Prefab();if(!prefab.Load("delve_wayrest_forest",true,true,false,false))throw new Exception("Wayrest missing");var doc=new XmlDocument();doc.Load(Path.Combine(folder,"wayrest-changes.xml"));int eligible=0,skipped=0,already=0;
 foreach(XmlElement e in doc.DocumentElement.ChildNodes){int x=int.Parse(e.GetAttribute("x")),y=int.Parse(e.GetAttribute("y")),z=int.Parse(e.GetAttribute("z"));int wx=x-2711,wy=y+63,wz=z-2182;Chunk c;if(!chunks.TryGetValue((wx>>4)+","+(wz>>4),out c))continue;int lx=wx&15,lz=wz&15;var before=c.GetBlock(lx,wy,lz);var after=prefab.GetBlock(x,y,z);var d=after.isTerrain?(sbyte)-127:(sbyte)127;
 if(before.rawData==after.rawData&&before.damage==after.damage&&c.GetDensity(lx,wy,lz)==d){already++;continue;}
 if(before.Block.GetBlockName()=="delveWayrestStewardSpawn"&&after.Block.GetBlockName()=="delveWayrestStewardSpawn"){if(c.GetDensity(lx,wy,lz)==127){already++;continue;}eligible++;if(apply){c.SetDensity(lx,wy,lz,127);dirty.Add(c);}continue;}
 string expected=e.GetAttribute("before");bool matches=before.Block.GetBlockName()==expected||(expected=="terrainFiller"&&before.isTerrain);if(!matches||before.rotation!=byte.Parse(e.GetAttribute("rotation"))||before.damage!=int.Parse(e.GetAttribute("damage"))||(c.GetTileEntity(new Vector3i(lx,wy,lz))!=null&&before.rawData!=after.rawData)){skipped++;report.AppendLine("PRESERVED "+wx+","+wy+","+wz+" "+before.Block.GetBlockName()+" expected="+expected);continue;}
 eligible++;if(apply){c.SetBlockRaw(lx,wy,lz,after);c.SetDensity(lx,wy,lz,d);c.GetSetTextureFullArray(lx,wy,lz,prefab.GetTexture(x,y,z));dirty.Add(c);}
 }
 int restored=0;doc.Load(Path.Combine(folder,"cells.xml"));foreach(XmlElement e in doc.DocumentElement.ChildNodes){int x=int.Parse(e.GetAttribute("x")),y=int.Parse(e.GetAttribute("y")),z=int.Parse(e.GetAttribute("z"));Chunk c;if(!chunks.TryGetValue((x>>4)+","+(z>>4),out c))continue;var before=c.GetBlock(x&15,y,z&15);if(before.Block.GetBlockName()==e.GetAttribute("after"))continue;if(before.Block.GetBlockName()!=e.GetAttribute("before")||before.damage!=0){report.AppendLine("PRESERVED modified crate location "+x+","+y+","+z);continue;}restored++;if(apply){var after=Block.GetBlockValue(e.GetAttribute("after"),false);after.rotation=before.rotation;c.SetBlockRaw(x&15,y,z&15,after);c.SetDensity(x&15,y,z&15,127);dirty.Add(c);}}
 report.AppendLine("Restored cart locations="+restored);
 int crates=0;foreach(var c in chunks.Values)for(int y=0;y<256;y++)for(int z=0;z<16;z++)for(int x=0;x<16;x++){var b=c.GetBlock(x,y,z);if(b.ischild||!b.Block.GetBlockName().StartsWith("cntShoppingCart"))continue;var pos=new Vector3i(x,y,z);var te=c.GetTileEntity(pos);if(te!=null){if(!(te is TileEntityComposite)||((TileEntityComposite)te).GetFeature<TEFeatureStorage>()==null)throw new Exception("Unexpected crate tile entity");continue;}crates++;if(apply){var t=new TileEntityComposite(c,b);t.localChunkPos=pos;c.AddTileEntity(t);dirty.Add(c);}}
 if(apply){foreach(var c in dirty){c.RecalcHeights();c.isModified=true;c.NeedsRegeneration=true;manager.SaveChunkSnapshot(c,true);}manager.WaitSaveDone();}
 report.AppendLine("PASS "+mode+" Wayrest eligible="+eligible+" already="+already+" preserved="+skipped+" crate storage added="+crates+" dirty chunks="+dirty.Count);File.WriteAllText(Path.Combine(folder,"batch03-"+mode+".txt"),report.ToString());return report.ToString();}
}

